import { Fragment, type ReactNode } from "react";
import type { PartProps } from "../../create-part";
import { SplitterHandle, SplitterPanel, SplitterRoot, type UseSplitterProps } from "./splitter";

export interface SplitterParts {
  readonly panel?: PartProps<"div"> | undefined;
  readonly handle?: PartProps<"div"> | undefined;
}

export interface SplitterComposedProps extends UseSplitterProps {
  readonly children?: ReactNode;
  readonly parts?: SplitterParts | undefined;
}

export function Splitter(props: SplitterComposedProps): ReactNode {
  const { children, parts, ...rest } = props;
  // Keyed, so a `panelSide` changed at runtime moves the handle instead of
  // remounting it and dropping its focus.
  const handle = <SplitterHandle key="handle" {...parts?.handle} />;
  const content = <Fragment key="content">{children}</Fragment>;
  const leading = rest.panelSide === "end";

  return (
    <SplitterRoot {...rest}>
      <SplitterPanel {...parts?.panel}>
        {leading ? [handle, content] : [content, handle]}
      </SplitterPanel>
    </SplitterRoot>
  );
}

export type {
  SplitterCollapsedChangeDetails,
  SplitterMachineProps,
  SplitterPanelSide,
  SplitterSizeChangeDetails,
  SplitterUnit,
  SplitterValueTextDetails,
} from "@standarui/core/splitter";
export { Splitter, type SplitterComposedProps, type SplitterParts } from "./composed";
export {
  type SplitterApi,
  SplitterHandle,
  SplitterPanel,
  SplitterRoot,
  type SplitterRootProps,
  type UseSplitterProps,
  useSplitter,
  useSplitterContext,
} from "./splitter";

import * as splitter from "@standarui/core/splitter";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";

export type SplitterApi = splitter.SplitterApi<ReactPropTypes>;

const SplitterContext = createPartContext<SplitterApi>("Splitter");

export interface UseSplitterProps extends splitter.SplitterMachineProps, MachineRuntimeProps {}

export function useSplitter(props: UseSplitterProps): SplitterApi {
  const host = useIntentScopeHost();

  return splitter.connect(
    useMachine(splitter.machine, {
      ...props,
      intents: props.intents === undefined ? host : props.intents,
    }),
    normalizeProps,
  );
}

export function useSplitterContext(): SplitterApi {
  return SplitterContext.usePart("SplitterContext");
}

export interface SplitterRootProps extends UseSplitterProps {
  readonly children?: ReactNode;
}

export function SplitterRoot(props: SplitterRootProps): ReactNode {
  const { children, ...machineProps } = props;
  const api = useSplitter(machineProps);

  return <SplitterContext.Provider value={api}>{children}</SplitterContext.Provider>;
}

export const SplitterPanel: (props: PartProps<"div">) => ReactNode = createPart(SplitterContext, {
  name: "SplitterPanel",
  element: "div",
  props: (api) => api.getPanelProps(),
});

export const SplitterHandle: (props: PartProps<"div">) => ReactNode = createPart(SplitterContext, {
  name: "SplitterHandle",
  element: "div",
  props: (api) => api.getHandleProps(),
});
